"""Union the .ai-log files across every side that holds any of them.

Three sources now: what is on disk (this session keeps appending), my
resolution at 0aa38c5, and what main carries after Hung's merge. Taking
any single one drops somebody's day, so keep every distinct line and
order by the `ts` each entry already carries. Only byte-identical lines
collapse -- those are one event recorded twice.
"""
import io, json, subprocess

PATHS = [".ai-log/archive/2026-08-20.jsonl",
         ".ai-log/archive/2026-08-23.jsonl",
         ".ai-log/session.jsonl"]

def from_git(rev, path):
    r = subprocess.run(["git", "show", f"{rev}:{path}"],
                       capture_output=True, text=True, encoding="utf-8", errors="replace")
    return [l for l in r.stdout.splitlines() if l.strip()] if r.returncode == 0 else []

def from_disk(path):
    try:
        return [l for l in io.open(path, encoding="utf-8", errors="replace").read().splitlines() if l.strip()]
    except FileNotFoundError:
        return []

def ts(line, i):
    try:
        return (json.loads(line).get("ts", ""), i)
    except Exception:
        return ("", i)

for path in PATHS:
    disk, mine, theirs = from_disk(path), from_git("0aa38c5", path), from_git("HEAD", path)
    seen, merged = set(), []
    for source in (disk, mine, theirs):
        for line in source:
            if line not in seen:
                seen.add(line)
                merged.append(line)
    merged.sort(key=lambda l: ts(l, 0))
    io.open(path, "w", encoding="utf-8", newline="\n").write("\n".join(merged) + "\n")
    now = set(merged)
    print(f"{path}")
    print(f"   dia={len(disk)} ban-toi={len(mine)} tren-main={len(theirs)} -> gop={len(merged)}")
    print(f"   mat cua dia={len(set(disk)-now)} mat cua ban-toi={len(set(mine)-now)} mat cua main={len(set(theirs)-now)}")
