"""Add the assistant page's own styles, ahead of the older chat block.

The `.chat-*` rules stay where they are: `AgentDock` reuses
`.chat-bubble`, so deleting them to tidy up would take the floating
dock's styling with them.
"""

import io

PATH = r"e:\VinAI\RoboMind_project\P-011\apps\web\src\app\globals.css"

ANCHOR = (
    "/* ===================================================================\n"
    "   Assistant chat\n"
    "   =================================================================== */\n"
)

BLOCK = """/* ===================================================================
   The assistant page
   ===================================================================
   The shape people already know: a thread that fills the screen, a
   composer pinned to the bottom of it. The reader's question is short
   and sits in a bubble on the right; the answer is long -- prose, tool
   evidence, sometimes a whole extracted paper -- and runs the full
   width of the column rather than being folded into a bubble sized for
   a chat message.
   =================================================================== */

.agent-page {
  display: flex;
  flex-direction: column;
  /* Fill what is left under the top bar, so the composer sits at the
     bottom of the screen and only the thread scrolls. */
  height: calc(100vh - var(--topbar-height) - var(--space-6));
  min-height: 420px;
}

.agent-head {
  display: flex;
  align-items: center;
  gap: var(--space-3);
  padding-bottom: var(--space-3);
  border-bottom: 1px solid var(--border);
}
.agent-head-text { min-width: 0; }
.agent-head-text h2 { margin: 0; }
.agent-head-text p { margin: 0; font-size: var(--fs-sm); }
.agent-head-badge { margin-left: auto; }
/* Without a badge to push it, the disclosure takes the slot itself. */
.agent-head-badge + .agent-boundaries { margin-left: var(--space-3); }
.agent-boundaries { margin-left: auto; position: relative; }
.agent-boundaries summary { cursor: pointer; white-space: nowrap; }
.agent-boundaries-body {
  position: absolute;
  z-index: 20;
  top: calc(100% + var(--space-2));
  right: 0;
  width: min(360px, 80vw);
  padding: var(--space-3);
  border: 1px solid var(--border);
  border-radius: 8px;
  background: var(--panel);
  box-shadow: var(--shadow);
}
.agent-boundaries-body p { margin: 0 0 var(--space-2); }
.agent-boundaries-body p:last-child { margin-bottom: 0; }

.agent-thread {
  flex: 1;
  overflow-y: auto;
  /* Room on the right so a scrollbar does not sit on the text. */
  padding: var(--space-4) var(--space-2) var(--space-4) 0;
}

/* One column, centred, capped at a comfortable measure. A thread that
